mapper.select:
SELECT id FROM experiment_run
 WHERE tenant_id = #{t} AND experiment_id = #{experimentId}
 ORDER BY id DESC LIMIT 1

mapper.update:
UPDATE manifest_placement
   SET position_id = #{positionId}, status = 'assigned', updated_at = now()
 WHERE tenant_id = #{t} AND id = #{placementId}

UPDATE manifest_placement
   SET status = 'verified', verified_by = #{verifiedBy}, verified_at = now(), updated_at = now()
 WHERE tenant_id = #{t} AND id = #{placementId}
